(function(){
'use strict';
const data=window.HUB_DATA, core=window.HubCore, esc=core.escapeHTML, main=document.getElementById('main');
const all=[...data.resources,...data.databases], byId=new Map(all.map(r=>[r.id,r]));
const external=(r,cls='')=>`<a class="${cls}" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.name)} <span aria-hidden="true">↗</span></a>`;
const groupOrder=['IRB and approvals','Forms and documents','REDCap and data tools','Study design and statistics','Literature and systematic reviews','Funding and career development','Writing and reporting','Clinical trials and collaboration','Getting started','Research support'];
function searchForm(value='',placeholder='Search resources, tools, or study names…'){return `<form class="search-form" data-search><label><span class="sr-only">Search resources</span><input type="search" name="q" aria-label="Search resources" value="${esc(value)}" placeholder="${esc(placeholder)}"></label><button>Search</button></form>`;}
function card(r,access=false){return `<article class="resource-card"><h3>${external(r)}</h3><p>${esc(r.summary)}</p>${access?`<details><summary>Access requirements</summary><p>${esc(r.access)}</p></details>`:''}</article>`;}
function groups(items,topics){return topics.map(t=>{const group=items.filter(r=>(r.type==='database'?r.topic:r.category)===t);return group.length?`<section class="topic-group"><h2>${esc(t)} <small>${group.length}</small></h2><div class="directory-grid">${group.map(r=>card(r,r.type==='database')).join('')}</div></section>`:'';}).join('');}
function pageHead(title,description){return `<section class="page-head"><div class="container"><h1>${esc(title)}</h1><p>${esc(description)}</p></div></section>`;}
function home(){return `<section class="hero"><div class="container home-intro"><p class="eyebrow">Clinical &amp; translational research</p><h1>Research resources.<br><em>One place. Direct access.</em></h1><p class="lead">For LSU Health New Orleans PCCM faculty and fellows—and students and residents starting a research project.</p>${searchForm()}</div></section><section class="section"><div class="container"><div class="section-heading"><h2>Frequently needed</h2><a href="#resources">All research resources →</a></div><div class="quick-links">${['irb-start','protocol-templates','consent-templates','redcap-login','redcap-start','lsu-biostatistics'].map(id=>{const r=byId.get(id);return `<div>${external(r)}<p>${esc(id==='redcap-login'?'Open your existing projects.':id==='lsu-biostatistics'?'Study design, sample size, and analysis support.':r.summary)}</p></div>`;}).join('')}</div></div></section><section class="section alt"><div class="container home-modules"><div><p class="eyebrow">Data for your next question</p><h2>PCCM Databases</h2><p>40 databases in 17 topics: critical care, pulmonary cohorts, imaging, population studies, and molecular data.</p><a class="button" href="#databases">Browse PCCM Databases →</a><p class="download-inline"><a href="${data.download}" download>Download the Word directory ↓</a></p></div><div><p class="eyebrow">Share work in progress</p><h2>PCCM research conference</h2><p><strong>2nd &amp; 4th Wednesdays · noon Central</strong></p><p>Present a new idea, work in progress, results, or a manuscript.</p><a class="button" href="#conferences">Schedule &amp; presenter sign-up →</a></div><div><p class="eyebrow">Low-friction project support</p><h2>Lowenstein PCCM Micro-Grants</h2><p>For LSU Health New Orleans medical students, residents, and fellows working on PCCM-related research.</p><a class="button" href="#microgrants">Apply or view recipients →</a></div></div></section><section class="section"><div class="container"><h2>More tools for your research</h2><div class="task-chips">${[['Study design and statistics','Design & statistics'],['Literature and systematic reviews','Literature searches'],['Funding and career development','Funding & career development'],['Writing and reporting','Writing & reporting'],['Clinical trials and collaboration','Trials & collaboration']].map(([key,label])=>`<a href="#resources?category=${encodeURIComponent(key)}">${label} →</a>`).join('')}</div></div></section>`;}
function directory(route,isDatabase=false){const topics=isDatabase?data.topics:groupOrder;const selected=route.params.get(isDatabase?'topic':'category')||'all';return pageHead(isDatabase?'PCCM Databases':'Research resources',isDatabase?'Browse by topic or search. Each title opens the database directly.':'Practical tools and support, grouped by task. Each title opens the official resource directly.')+`<div class="container directory-section">${isDatabase?`<p class="directory-download"><a href="${data.download}" download>Download the PCCM database directory (Word) ↓</a></p>`:''}<div class="directory-controls">${searchForm(route.params.get('q')||'')}<label>${isDatabase?'Database topic':'Research task'}<select id="directory-filter"><option value="all">All ${isDatabase?'17 topics':'tasks'}</option>${topics.map(t=>`<option value="${esc(t)}" ${selected===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label></div><p id="results-count" role="status"></p><div id="directory-results"></div></div>`;}
function conferences(){return pageHead('PCCM research conference','Second and fourth Wednesdays at noon · Central Time')+`<div class="container section"><div class="conference-intro"><div><h2>Present your research</h2><p>Choose a date and add your name, LSU Health email, and presentation topic. New projects, work in progress, results, and manuscripts are welcome.</p><p class="quiet-note">Dates follow the section’s recurring schedule. Location and any holiday changes will be confirmed by the section.</p></div><a href="${esc(data.conferenceUrl)}" target="_blank" rel="noopener noreferrer">LSU Health PCCM conferences ↗</a></div><div id="research-schedule" aria-live="polite"></div><div id="booking-panel"></div></div>`;}
function microgrants(){const recipients=data.micrograntRecipients||[];return pageHead('Lowenstein PCCM Micro-Grants','Small requests. A short application. Support for PCCM-related research.')+`<div class="container section grants-layout"><article><h2>Apply for project support</h2><p>Open to LSU Health New Orleans <strong>medical students, residents, and fellows</strong> working on pulmonary or critical care research.</p><p>Tell us briefly what you are studying, what you need, and how much funding you are requesting. No proposal attachment or CV is needed.</p><form id="microgrant-form" class="application-form"><div class="form-pair"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>LSU Health email<input name="email" type="email" autocomplete="email" placeholder="you@lsuhsc.edu" pattern="[^@\\s]+@lsuhsc\\.edu" required maxlength="254"></label></div><label>Training level<select name="level" required><option value="">Select your training level</option><option>Medical student</option><option>Resident</option><option>Fellow</option></select></label><label>1. Short description of your research project<textarea name="project" rows="4" required maxlength="2500" placeholder="What question are you asking, and how will you study it?"></textarea></label><label>2. What do you need the funds for?<textarea name="need" rows="3" required maxlength="2000" placeholder="Describe the items, services, or other project costs."></textarea></label><label>3. Budget requested (USD)<input name="budget" type="number" min="1" max="10000000" step="0.01" inputmode="decimal" required placeholder="Amount requested"></label><div class="form-trap" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><p class="quiet-note">Do not include patient names, identifiers, or confidential study data. Applications are reviewed before funding decisions are made.</p><button class="button" type="submit" id="grant-submit">Submit application</button><p id="grant-status" role="status" tabindex="-1"></p></form></article><aside class="grant-aside"><p class="eyebrow">A simple request</p><h2>Three things we need</h2><ol><li>A short project description</li><li>What the funding will pay for</li><li>The amount requested</li></ol><p>For research related to pulmonary and critical care medicine.</p></aside></div><section class="section alt" id="recipients"><div class="container"><h2>Lowenstein PCCM Micro-Grants recipients</h2><p>Recipients and the PCCM research projects supported by this program.</p>${recipients.length?`<div class="directory-grid">${recipients.map(r=>`<article class="resource-card"><p class="card-tag">${esc(r.level)}${r.year?' · '+esc(r.year):''}</p><h3>${esc(r.name)}</h3><h4>${esc(r.project)}</h4><p>${esc(r.summary)}</p></article>`).join('')}</div>`:'<p class="recipient-empty">Recipient names and project summaries will be posted here as awards are announced.</p>'}</div></section>`;}
function about(){return pageHead('About CTS Research Hub','Research resources for the LSU Health New Orleans PCCM community.')+`<div class="container section about-copy"><p>This hub brings together PCCM databases, institutional research tools, funding, study design support, and opportunities to present and develop research.</p><p>Resource titles link directly to their official sources. The hub is hosted outside the LSU Health institutional website; official policies, services, and access requirements remain with the linked offices.</p><p>The Lowenstein PCCM Micro-Grants program supports PCCM-related projects by LSU Health New Orleans medical students, residents, and fellows.</p><a class="button outline" href="#resources">Browse research resources →</a></div>`;}
let current,searchValue='',filterValue='all';
function updateResults(){if(!['resources','databases'].includes(current.page))return;const isDb=current.page==='databases',searchPool=isDb?data.databases:all,options={query:searchValue};if(isDb)options.topic=filterValue;else options.category=filterValue;let items=core.filterResources(searchPool,options);if(!isDb&&!searchValue)items=items.filter(r=>r.type!=='database');const groupedTopics=isDb?data.topics:[...groupOrder,...(searchValue?data.topics:[])];document.getElementById('results-count').textContent=`${items.length} ${isDb?'databases':'resources'}`;document.getElementById('directory-results').innerHTML=items.length?groups(items,groupedTopics):'<p class="empty">No matches. Try another term or research task.</p>';}
function bind(){document.querySelectorAll('[data-search]').forEach(form=>{form.addEventListener('submit',event=>{event.preventDefault();const q=new FormData(form).get('q').trim();if(['resources','databases'].includes(current.page)){searchValue=q;updateResults();}else location.hash='#resources?q='+encodeURIComponent(q);});if(['resources','databases'].includes(current.page))form.querySelector('input').addEventListener('input',event=>{searchValue=event.target.value;updateResults();});});document.getElementById('directory-filter')?.addEventListener('change',event=>{filterValue=event.target.value;updateResults();});if(current.page==='conferences')window.HubSchedule.mount(current.params);if(current.page==='microgrants')window.HubSchedule.bindGrant();}
function render(){current=core.parseRoute(location.hash);if(current.page==='detail'){const r=byId.get(current.id);main.innerHTML=r?pageHead(r.name,r.summary)+`<div class="container section"><p>${esc(r.access)}</p>${external(r,'button')}</div>`:pageHead('Resource not found','Browse the directory for available resources.');return;}const titles={home:'CTS Research Hub',resources:'Research resources',databases:'PCCM Databases',conferences:'PCCM research conference',microgrants:'Lowenstein PCCM Micro-Grants',about:'About'};document.title=titles[current.page]+(current.page==='home'?'':' | CTS Research Hub');document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===current.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('primary-nav').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');searchValue=current.params.get('q')||'';filterValue=current.params.get(current.page==='databases'?'topic':'category')||'all';main.innerHTML=current.page==='home'?home():['resources','databases'].includes(current.page)?directory(current,current.page==='databases'):current.page==='conferences'?conferences():current.page==='microgrants'?microgrants():about();bind();updateResults();window.scrollTo(0,0);}
document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.getElementById('primary-nav').classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));});window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return;}render();main.focus({preventScroll:true});});render();
})();
